199	// ---------------------------------------------------------------------------
200	// Hilfsfunktion: fetch mit lesbarer Fehlermeldung
201	// ---------------------------------------------------------------------------
202	
203	/**
204	 * Wirft eine lesbare Meldung statt eines rohen Response-Objekts, damit die UI
205	 * direkt `error.message` anzeigen kann ("Backend not reachable – start uvicorn").
206	 */
207	async function request<T>(path: string, init?: RequestInit): Promise<T> {
208	  let response: Response;
209	  try {
210	    response = await fetch(`${BASE_URL}${path}`, {
211	      headers: { "Content-Type": "application/json" },
212	      ...init,
213	    });
214	  } catch {
215	    throw new Error("Backend not reachable – start uvicorn");
216	  }
217	
218	  if (!response.ok) {
219	    const detail = await response
220	      .json()
221	      .then((body: { detail?: string }) => body.detail)
222	      .catch(() => undefined);
223	    throw new Error(detail ?? `Request failed: ${response.status} ${response.statusText}`);
224	  }
225	
226	  return response.json() as Promise<T>;
227	}
