260	export function putWeights(scenarioId: string, input: WeightsInput): Promise<Requirement[]> {
261	  return request<Requirement[]>(`/api/scenarios/${encodeURIComponent(scenarioId)}/weights`, {
262	    method: "PUT",
263	    body: JSON.stringify(input),
