266	
267	export function getAudit(filter?: {
268	  scenarioId?: string;
269	  requirementId?: string;
270	}): Promise<AuditEvent[]> {
271	  const params = new URLSearchParams();
272	  if (filter?.scenarioId) params.set("scenario_id", filter.scenarioId);
273	  if (filter?.requirementId) params.set("requirement_id", filter.requirementId);
274	  const query = params.toString();
275	  return request<AuditEvent[]>(`/api/audit${query ? `?${query}` : ""}`);
276	}
277	
278	export function getAuditVerify(): Promise<AuditVerifyResult> {
279	  return request<AuditVerifyResult>("/api/audit/verify");
280	}
