1	"use client";
2	
3	import { useEffect, useMemo, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import {
6	  getExportUrl,
7	  getRequirements,
8	  getScenarios,
9	  getSignals,
10	  type Requirement,
11	  type Scenario,
12	  type Signal,
13	} from "@/src/lib/api";
14	import { categoryLabel, ConflictBadge, EvidenceBadge, StatusBadge } from "@/src/components/badges";
15	import { ScoreBar } from "@/src/components/ScoreBar";
16	
17	const DEFAULT_SCENARIO_ID = "G60-US";
18	
19	export default function RequirementsPage() {
20	  const router = useRouter();
21	
22	  const [scenarios, setScenarios] = useState<Scenario[] | null>(null);
23	  const [scenarioId, setScenarioId] = useState<string>(DEFAULT_SCENARIO_ID);
24	  const [requirements, setRequirements] = useState<Requirement[] | null>(null);
25	  const [signals, setSignals] = useState<Signal[] | null>(null);
26	  const [error, setError] = useState<string | null>(null);
27	  const [isFetching, setIsFetching] = useState(true);
28	
29	  // Szenarien einmal laden; Standard bleibt G60-US, falls vorhanden, sonst erstes Szenario.
30	  useEffect(() => {
31	    getScenarios()
32	      .then((loaded) => {
33	        setScenarios(loaded);
34	        if (!loaded.some((s) => s.id === DEFAULT_SCENARIO_ID) && loaded[0]) {
35	          setScenarioId(loaded[0].id);
36	        }
37	      })
38	      .catch((err: Error) => setError(err.message));
39	  }, []);
40	
41	  // Anforderungen + Befunde (für Konflikt-Check) neu laden bei Szenario-Wechsel.
42	  useEffect(() => {
43	    if (!scenarioId) return;
44	    let cancelled = false;
45	    (async () => {
46	      setIsFetching(true);
47	      try {
48	        const [loadedRequirements, loadedSignals] = await Promise.all([
49	          getRequirements(scenarioId),
50	          getSignals(scenarioId),
51	        ]);
52	        if (cancelled) return;
53	        setRequirements(loadedRequirements);
54	        setSignals(loadedSignals);
55	        setError(null);
56	      } catch (err) {
57	        if (cancelled) return;
58	        setError((err as Error).message);
59	      } finally {
60	        if (!cancelled) setIsFetching(false);
61	      }
62	    })();
63	    return () => {
64	      cancelled = true;
65	    };
66	  }, [scenarioId]);
67	
68	  const signalsById = useMemo(() => {
69	    const map = new Map<string, Signal>();
70	    for (const signal of signals ?? []) map.set(signal.id, signal);
71	    return map;
72	  }, [signals]);
73	
74	  /** Titel der gegensätzlichen Befunde, falls ein verknüpfter Befund `conflicts_with` hat. */
75	  function conflictingTitlesFor(requirement: Requirement): string[] {
76	    const titles: string[] = [];
77	    for (const signalId of requirement.signal_ids) {
78	      const signal = signalsById.get(signalId);
79	      for (const otherId of signal?.conflicts_with ?? []) {
80	        titles.push(signalsById.get(otherId)?.title ?? otherId);
81	      }
82	    }
83	    return titles;
84	  }
85	
86	  const isLoading = scenarios === null || isFetching || requirements === null || signals === null;
87	
88	  return (
89	    <div className="min-h-screen bg-zinc-50">
90	      <header className="border-b border-zinc-200 bg-white">
91	        <div className="mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-6 py-5">
92	          <div>
93	            <h1 className="text-xl font-semibold text-[#0b1f3a]">Signal2Spec · PM Cockpit</h1>
94	            <p className="text-sm text-zinc-500">Prioritized requirements for product decisions</p>
95	          </div>
96	          <div className="flex items-center gap-3">
97	            <label className="flex items-center gap-2 text-sm text-zinc-700">
98	              Scenario
99	              <select
100	                value={scenarioId}
101	                onChange={(e) => setScenarioId(e.target.value)}
102	                disabled={!scenarios}
103	                className="rounded-md border border-zinc-300 bg-white px-3 py-1.5 text-sm text-[#0b1f3a] focus:border-blue-500 focus:outline-none"
104	              >
105	                {(scenarios ?? []).map((s) => (
106	                  <option key={s.id} value={s.id}>
107	                    {s.model_name} ({s.market})
108	                  </option>
109	                ))}
110	              </select>
111	            </label>
112	            <a
113	              href={getExportUrl(scenarioId)}
114	              target="_blank"
115	              rel="noopener noreferrer"
116	              className="rounded-md bg-blue-600 px-4 py-1.5 text-sm font-medium text-white hover:bg-blue-700"
117	            >
118	              Export CSV
119	            </a>
120	          </div>
121	        </div>
122	      </header>
123	
124	      <main className="mx-auto max-w-6xl px-6 py-8">
125	        {error && (
126	          <div className="rounded-md border border-rose-300 bg-rose-50 px-4 py-3 text-sm text-rose-800">
127	            {error}
128	          </div>
129	        )}
130	
131	        {!error && isLoading && <p className="text-sm text-zinc-500">Loading…</p>}
132	
133	        {!error && !isLoading && requirements !== null && requirements.length === 0 && (
134	          <p className="text-sm text-zinc-500">No requirements for this scenario yet.</p>
135	        )}
136	
137	        {!error && !isLoading && requirements !== null && requirements.length > 0 && (
138	          <div className="overflow-hidden rounded-lg border border-zinc-200 bg-white">
139	            <table className="w-full text-left text-sm">
140	              <thead className="border-b border-zinc-200 bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500">
141	                <tr>
142	                  <th className="px-4 py-3">Rank</th>
143	                  <th className="px-4 py-3">Title</th>
144	                  <th className="px-4 py-3">Score</th>
145	                  <th className="px-4 py-3">Evidence</th>
146	                  <th className="px-4 py-3">Category</th>
147	                  <th className="px-4 py-3">Status</th>
148	                  <th className="px-4 py-3">Conflict</th>
149	                </tr>
150	              </thead>
151	              <tbody>
152	                {requirements.map((req) => {
153	                  const conflicts = conflictingTitlesFor(req);
154	                  return (
155	                    <tr
156	                      key={req.id}
157	                      role="link"
158	                      tabIndex={0}
159	                      onClick={() => router.push(`/requirements/${req.id}`)}
160	                      onKeyDown={(e) => {
161	                        if (e.key === "Enter" || e.key === " ") {
162	                          e.preventDefault();
163	                          router.push(`/requirements/${req.id}`);
164	                        }
165	                      }}
166	                      className="cursor-pointer border-b border-zinc-100 last:border-0 hover:bg-blue-50 focus:bg-blue-50 focus:outline-none"
167	                    >
168	                      <td className="px-4 py-3 font-medium text-zinc-500">#{req.rank}</td>
169	                      <td className="px-4 py-3 font-medium text-[#0b1f3a]">{req.title}</td>
170	                      <td className="px-4 py-3">
171	                        <ScoreBar score={req.score} />
172	                      </td>
173	                      <td className="px-4 py-3">
174	                        <EvidenceBadge level={req.evidence_level} reason={req.rationale} />
175	                      </td>
176	                      <td className="px-4 py-3 text-zinc-700">{categoryLabel(req.category)}</td>
177	                      <td className="px-4 py-3">
178	                        <StatusBadge status={req.status} />
179	                      </td>
180	                      <td className="px-4 py-3">
181	                        <ConflictBadge conflictingTitles={conflicts} />
182	                      </td>
183	                    </tr>
184	                  );
185	                })}
186	              </tbody>
187	            </table>
188	          </div>
189	        )}
190	      </main>
191	    </div>
192	  );
193	}
